// 1. Filtra mensagens enviadas pelo próprio bot
const body = $input.first().json.body || $input.first().json;

if (!body || !body.data || body.data.key?.fromMe) {
  return [];
}

const key = body.data.key;
const message = body.data.message || {};
const pushName = body.data.pushName || 'Colaborador da Obra';
const remoteJid = key.remoteJid || '';
const isGroup = remoteJid.endsWith('@g.us');

// 2. Extrai tipo de mensagem
let messageType = 'text';
let rawText = '';
let mediaUrl = '';
let isAudio = false;
let isImage = false;

if (message.conversation || message.extendedTextMessage?.text) {
  messageType = 'text';
  rawText = message.conversation || message.extendedTextMessage.text;
} else if (message.audioMessage) {
  messageType = 'audio';
  isAudio = true;
  rawText = '[Áudio WhatsApp]';
} else if (message.imageMessage) {
  messageType = 'image';
  isImage = true;
  rawText = message.imageMessage.caption || '[Foto de Canteiro sem legenda]';
}

return [{
  json: {
    instanceName: body.instance || 'construkore-obra',
    whatsapp_message_id: key.id,
    remoteJid,
    isGroup,
    sender_phone: remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', ''),
    sender_name: pushName,
    messageType,
    rawText,
    isAudio,
    isImage,
    received_at: new Date().toISOString()
  }
}];

// Classificador e Extrator de Entidades de Canteiro
const input = $input.first().json;
const text = input.text || input.rawText || '';

let category = 'PRODUCTION_PROGRESS';
let suggestedQuantity = null;
let suggestedUom = 'm²';
let taskName = 'Atividade de Canteiro';
let isCritical = false;
let materialShortage = null;

// 1. Detecção de Quantidades e Metragens
const numMatch = text.match(/(\d+(?:[,.]\d+)?)\s*(m²|m2|metros quadrados|m³|m3|caminhões|pontos|barras)?/i);
if (numMatch) {
  suggestedQuantity = parseFloat(numMatch[1].replace(',', '.'));
  if (numMatch[2]) {
    const rawUom = numMatch[2].toLowerCase();
    suggestedUom = rawUom.includes('3') ? 'm³' : rawUom.includes('ponto') ? 'pontos' : 'm²';
  }
}

// 2. Detecção de Falta de Material / Suprimentos
if (/faltou|acabou|sem estoque|não entregou|atraso no cimento|falta de bloco/i.test(text)) {
  category = 'MATERIAL_SHORTAGE';
  materialShortage = {
    material_name: /bloco/i.test(text) ? 'Bloco Cerâmico' : /cimento/i.test(text) ? 'Cimento CP-II' : 'Insumo Crítico',
    workers_idle: 4,
    hours_lost: 2.0
  };
}

// 3. Detecção de Tarefa Crítica (Concretagem / Escoramento)
if (/concreta|laje|viga|slump|escoramento/i.test(text)) {
  taskName = 'Concretagem de Vigas e Lajes';
  isCritical = true;
} else if (/reboco|gesso/i.test(text)) {
  taskName = 'Reboco Interno Gesso';
} else if (/alvenaria|bloco/i.test(text)) {
  taskName = 'Alvenaria Estrutural';
}

// 4. Monta Payload Normalizado para o ConstruKore RDO
return [{
  json: {
    whatsapp_message_id: input.whatsapp_message_id,
    sender_phone: input.sender_phone,
    sender_name: input.sender_name,
    message_type: input.messageType,
    raw_text: input.rawText,
    transcription: input.text || input.rawText,
    media_url: input.mediaUrl || (input.isImage ? 'https://images.unsplash.com/photo-1541888946425-d0fbb180c5f7' : undefined),
    received_at: input.received_at,
    detected_entities: {
      wbs_task_name: taskName,
      production_quantity: suggestedQuantity,
      uom: suggestedUom,
      occurrence_category: category === 'MATERIAL_SHORTAGE' ? 'material' : undefined,
      is_critical_activity: isCritical,
      material_shortage: materialShortage
    }
  }
}];

