// Sorteio Aleatório de Variações de Perguntas (Biblioteca Natural)
const templates = [
  'Boa tarde {nome}! Como está o andamento da {tarefa} no {local} hoje? Conseguiu fechar quantos {uom}?',
  'Fala {nome}, beleza? Me passa o resumo de produção de {tarefa} no {local} para fecharmos o diário.',
  'Olá {nome}, tudo certo? A equipe conseguiu bater a meta diária de {tarefa} no {local}? Quanto rendeu aproximadamente?',
  'Opa {nome}! A equipe avançou bem em {tarefa} ({local})? Manda um áudio rápido com a metragem aproximada fechada hoje.',
  '{nome}, fechamento de medição às 16:30: favor confirmar a produção de {tarefa} no {local} para o RDO.'
];

const chosenTemplate = templates[Math.floor(Math.random() * templates.length)];

return [{
  json: {
    template: chosenTemplate,
    scheduled_at: new Date().toISOString()
  }
}];
